private typealias Check=(JsonElement)->Unit
private val id:Check=CharterGrammar::id
private val v4:Check={id(it);require(CharterGrammar.text(it)[14]=='4')}
private val n:Check={CharterGrammar.number(it)}
private val positive:Check={require(CharterGrammar.number(it)>0)}
private val counter:Check={require(CharterGrammar.amount(it)<=Long.MAX_VALUE.toBigInteger())}
private val amount:Check={CharterGrammar.amount(it)}
private val hash:Check={CharterGrammar.hex(it,32)}
private val no:Check={require(!CharterGrammar.bool(it))}
private val bool:Check={CharterGrammar.bool(it)}
private val one:Check={require(CharterGrammar.number(it)==1L)}
private val key:Check={require(CharterGrammar.text(it).length in 1..128)}
private fun choice(vararg values:String):Check={require(CharterGrammar.text(it) in values)}
private fun nullable(check:Check):Check={if(it!=JsonNull)check(it)}
private fun obj(vararg fields:Pair<String,Check>):Check={x->val o=x.jsonObject;require(o.keys==fields.map{it.first}.toSet());fields.forEach{(k,c)->c(o.getValue(k))}}
private fun arr(max:Int,check:Check):Check={x->val a=x.jsonArray;require(a.size<=max);a.forEach(check)}
private fun base58(value:JsonElement,size:Int){val s=CharterGrammar.text(value);require(s.length in 1..88);var x=BigInteger.ZERO;for(c in s){val digit="123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz".indexOf(c);require(digit>=0);x=x*58.toBigInteger()+digit.toBigInteger()};require((x.bitLength()+7)/8+s.takeWhile{it=='1'}.length==size)}
private val address:Check={base58(it,32);require(CharterGrammar.text(it)!="1".repeat(32))}
private val signature:Check={base58(it,64)}
private fun timestamp(digits:Int):Check={val s=CharterGrammar.text(it);require(s.matches(Regex("[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\\.[0-9]{$digits}Z")));val time=Instant.parse(s);require(time.atOffset(java.time.ZoneOffset.UTC).year in 0..9999);require(java.time.format.DateTimeFormatter.ofPattern("uuuu-MM-dd'T'HH:mm:ss.${"S".repeat(digits)}'Z'").withZone(java.time.ZoneOffset.UTC).format(time)==s)}
private val time=timestamp(3);private val journalTime=timestamp(6)
private val family=choice("survey_balloon","cargo_cutter","courier_airship","expedition_barge")
private val tier:Check={require(CharterGrammar.number(it) in 1..255)}
private val identity=obj("assetId" to address,"collection" to address,"family" to family,"tier" to tier)
private val installRequest=obj("baseId" to id,"berthId" to id,"assetId" to address,"idempotencyKey" to key)
private val serviceRequest=obj("installationId" to id,"assetId" to address,"operation" to choice("upgrade","restore_uses"),"idempotencyKey" to key)
private val serviceState=obj("operation" to choice("upgrade","restore_uses"),"installationId" to id,"baseId" to id,"berthId" to id,"revision" to {require(CharterGrammar.number(it)<9_007_199_254_740_991L)},"family" to family,"tier" to tier,"completedTotal" to counter,"allowanceStart" to counter)
private fun preparation(service:Boolean)=obj("messageHex" to {CharterGrammar.hex(it,max=1167)},"messageSha256" to hash,*if(service)arrayOf("serviceSha256" to hash) else emptyArray(),"blockhash" to address,"blockhashContextSlot" to n,"lastValidBlockHeight" to n,"recordedAt" to journalTime)
private val signed=obj("signature" to signature,"wireSha256" to hash,"messageSha256" to hash,"acceptedAt" to journalTime)
private val installResult=obj("installationId" to v4,"baseId" to id,"berthId" to id,"assetId" to address,"family" to family,"tier" to tier,"installedWallet" to address,"installedAt" to journalTime,"signature" to signature)
private val serviceResult=obj("tierAfter" to tier,"revisionAfter" to n,"completedTotal" to counter,"allowanceStartAfter" to counter,"remainingUses" to n,"appliedAt" to journalTime,"signature" to signature)
private val referenceCheck=obj("kind" to choice("installation","service"),"id" to v4)
private val source=obj("genesisHash" to address,"anchorSlot" to n,"reviewedDeploymentSlot" to n,"reviewedProgramDataSha256" to hash)
private val receipt=obj("signature" to signature,"messageSha256" to hash,"wireSha256" to hash,"slot" to n,"finalizedThroughSlot" to n,"feeLamports" to amount,"assetRefundLamports" to amount)
private val reviewReasons=arrayOf("NOT_PREPARED","TERMINAL","PAUSED","PROVIDER_UNAVAILABLE","IDENTITY","OWNERSHIP","EXPIRED_UNRESOLVED","INSUFFICIENT_SOL","FEE_LIMIT","OBSERVED_TRANSACTION","TIMEOUT","BUSY")
private val observation=obj("genesisHash" to address,"core" to obj("reviewedDeploymentSlot" to n,"reviewedProgramDataSha256" to hash,"upgradeAuthority" to nullable(address)),"ownerWallet" to address,*listOf("ownerSlot","feeSlot","balanceSlot","validitySlot","closingSlot").map{it to n}.toTypedArray(),"blockhash" to address,"lastValidBlockHeight" to n,"currentBlockHeight" to n,"blockhashValid" to {require(CharterGrammar.bool(it))},"networkFeeLamports" to amount,"payerLamports" to amount)
