private val expeditionRequest:Check={x->val o=x.jsonObject;baseExpeditionRequest(JsonObject(o-"fitting"));o["fitting"]?.let{EquipmentPolicy.selection(it.jsonObject)}}
private val expeditionReturn:Check={x->val o=x.jsonObject;obj("returnId" to id,"returnedAt" to time,"completedTotal" to counter)(JsonObject(o-"secondaryOutput"));o["secondaryOutput"]?.let{equipmentSecondary(it.jsonObject)}}
