/** Strict public history shapes. They grant no RPC, ownership, signing or finality
 * authority; independent message/receipt verification and live reads are separate. */
object VehicleProtocol {
 fun copy(raw:JsonElement):JsonElement {var nodes=0;fun visit(v:JsonElement,depth:Int):JsonElement {require(++nodes<=50000&&depth<=20);return when(v){is JsonObject->{require(v.size<=64);JsonObject(v.mapValues{(k,x)->require(k.length<=64);visit(x,depth+1)})};is JsonArray->{require(v.size<=512);JsonArray(v.map{visit(it,depth+1)})};is JsonPrimitive->v.also{require(it.content.length<=4096)}}};return visit(raw,0)}
 fun encodeKey(value:String):String {key(JsonPrimitive(value));return value.toByteArray(Charsets.UTF_8).joinToString(""){b->val n=b.toInt() and 255;val c=n.toChar();if(c in 'a'..'z'||c in 'A'..'Z'||c in '0'..'9'||c in "-_.!~*'()")c.toString() else "%%%02X".format(n)}}
 fun byKeyPath(kind:String,key:String):String {require(kind in listOf("installation","service","expedition"));return if(kind=="expedition"){id(JsonPrimitive(key));"/advanced-expeditions/by-key/$key"} else "/vehicles/client/${if(kind=="installation")"installations" else "services"}/by-key/${encodeKey(key)}"}
 fun reference(raw:JsonObject):JsonObject {val r=raw.charterObject("record");return buildJsonObject{put("kind",raw.getValue("kind"));put("id",if(raw.charterText("kind")=="installation")r.charterObject("reservation").getValue("reservationId") else r.charterObject("intent").getValue("intentId"))}}
 fun actor(raw:JsonObject)=raw.charterObject("record").charterText("wallet")
 fun original(raw:JsonObject)=raw.charterObject("record").charterObject(if(raw.charterText("kind")=="installation")"reservation" else "intent")
 fun request(raw:JsonObject)=original(raw).charterObject("request")
 fun destination(raw:JsonObject):JsonObject {val r=if(raw.charterText("kind")=="installation")request(raw) else original(raw).charterObject("state");return buildJsonObject{put("baseId",r.getValue("baseId"));put("berthId",r.getValue("berthId"))}}
 fun terminal(raw:JsonObject)=raw.charterObject("record").charterOptional(if(raw.charterText("kind")=="installation")"installation" else "application")
 fun client(input:JsonObject):JsonObject {val v=copy(input).jsonObject;val kind=v.charterText("kind");require(kind in listOf("installation","service"));obj("version" to one,"kind" to choice(kind),"record" to {record(it.jsonObject,kind)},"consentSource" to nullable(source),"burnReceipt" to nullable(receipt))(v)
  val r=v.charterObject("record");val p=r.charterOptional("preparation");val s=r.charterOptional("signed");val src=v.charterOptional("consentSource");val burn=v.charterOptional("burnReceipt");val end=terminal(v)
  require((p==null)==(src==null)&&(end==null)==(burn==null));src?.let{require(CharterGrammar.number(it.getValue("anchorSlot"))>=CharterGrammar.number(it.getValue("reviewedDeploymentSlot"))&&CharterGrammar.number(p!!.getValue("blockhashContextSlot"))>=CharterGrammar.number(it.getValue("anchorSlot")))}
  burn?.let{require(it["messageSha256"]==p!!["messageSha256"]&&it["signature"]==end!!["signature"]);if(s!=null)require(it["wireSha256"]==s["wireSha256"]&&it["signature"]==s["signature"]);require(CharterGrammar.number(it.getValue("slot"))>CharterGrammar.number(src!!.getValue("anchorSlot"))&&CharterGrammar.number(it.getValue("finalizedThroughSlot"))>=CharterGrammar.number(it.getValue("slot")))}
  return v
 }
 private fun record(r:JsonObject,kind:String) {val service=kind=="service";val original=if(service)"intent" else "reservation";val end=if(service)"application" else "installation"
  val originalCheck=if(service)obj("intentId" to v4,"wallet" to address,"request" to serviceRequest,"identity" to identity,"state" to serviceState,"reservedAt" to journalTime) else obj("reservationId" to v4,"wallet" to address,"request" to installRequest,"identity" to identity,"completedBuildJobId" to id,"berthCompletedAt" to journalTime,"reservedAt" to journalTime)
  obj("version" to one,"purpose" to choice(if(service)"vehicle_service" else "vehicle_installation"),"wallet" to address,"idempotencyKey" to key,"serverNow" to time,original to originalCheck,"status" to choice("reserved","prepared","signed",if(service)"applied" else "installed"),"preparation" to nullable(preparation(service)),"signed" to nullable(signed),end to nullable(if(service)serviceResult else installResult),"signingAuthorized" to no,"broadcastAuthorized" to no,"reservationReleaseAuthorized" to no,(if(service)"serviceAuthorized" else "installationAuthorized") to no)(r)
  val o=r.charterObject(original);val request=o.charterObject("request");val ident=o.charterObject("identity");require(ident["assetId"]!=ident["collection"]&&r["wallet"]==o["wallet"]&&r["idempotencyKey"]==request["idempotencyKey"]&&request["assetId"]==ident["assetId"])
  if(service){val state=o.charterObject("state");require(o["intentId"]!=state["installationId"]&&request["installationId"]==state["installationId"]&&request["operation"]==state["operation"]&&ident["family"]==state["family"]&&ident["tier"]==state["tier"]);require(CharterGrammar.amount(state.getValue("allowanceStart"))<=CharterGrammar.amount(state.getValue("completedTotal")))}
  val p=r.charterOptional("preparation");val s=r.charterOptional("signed");val terminal=r.charterOptional(end);require(r.charterText("status")==if(terminal!=null)if(service)"applied" else "installed" else if(s!=null)"signed" else if(p!=null)"prepared" else "reserved");require((s==null&&terminal==null)||p!=null)
  s?.let{require(it["messageSha256"]==p!!["messageSha256"])};terminal?.let{if(s!=null)require(it["signature"]==s["signature"]);if(!service){require(it["installationId"]==o["reservationId"]&&it["installedWallet"]==r["wallet"]);for(k in listOf("baseId","berthId","assetId"))require(it[k]==request[k]);for(k in listOf("family","tier"))require(it[k]==ident[k])}}
 }
 fun review(raw:JsonObject):JsonObject=copy(raw).jsonObject.also{v->obj("version" to one,"reference" to referenceCheck,"wallet" to address,"messageSha256" to nullable(hash),"reviewedAt" to time,"expiresAt" to time,"status" to choice("ready","held"),"reason" to nullable(choice(*reviewReasons)),"observation" to nullable(observation),"signingAuthorized" to no,"broadcastAuthorized" to no,"reservationReleaseAuthorized" to no)(v);require(Instant.parse(v.charterText("expiresAt"))>Instant.parse(v.charterText("reviewedAt")));val o=v.charterOptional("observation");if(v.charterText("status")=="ready"){require(v["reason"]==JsonNull&&v["messageSha256"]!=JsonNull&&o!=null&&o["ownerWallet"]==v["wallet"]);require(CharterGrammar.number(o.getValue("currentBlockHeight"))<=CharterGrammar.number(o.getValue("lastValidBlockHeight")));require(listOf("ownerSlot","feeSlot","balanceSlot","validitySlot","closingSlot").map{CharterGrammar.number(o.getValue(it))}.zipWithNext().all{(a,b)->a<=b});require(CharterGrammar.amount(o.getValue("payerLamports"))>=CharterGrammar.amount(o.getValue("networkFeeLamports")))}else require(v["reason"]!=JsonNull&&o==null)}
 fun delivery(raw:JsonObject):JsonObject=copy(raw).jsonObject.also{v->obj("version" to one,"reference" to referenceCheck,"status" to choice("held","terminal","observed","submitted"),"reason" to nullable(choice("NOT_SIGNED","PAUSED","PROVIDER_UNAVAILABLE","IDENTITY","OWNERSHIP","EXPIRED_UNRESOLVED","INSUFFICIENT_SOL","FEE_LIMIT","OBSERVED_TRANSACTION","SEND_UNCERTAIN","TIMEOUT","BUSY")),"signature" to nullable(signature),"client" to {client(it.jsonObject)},"broadcastAuthorized" to no,"reservationReleaseAuthorized" to no)(v);val c=v.charterObject("client");require(v["reference"]==reference(c));require(v["signature"]==(c.charterObject("record").charterOptional("signed")?.get("signature")?:c.charterOptional("burnReceipt")?.get("signature")?:JsonNull));if(v.charterText("status")=="terminal")require(terminal(c)!=null);require((v.charterText("status")=="held")== (v["reason"]!=JsonNull));if(v.charterText("status") in listOf("submitted","observed"))require(v["signature"]!=JsonNull)}
 fun activity(raw:JsonObject):JsonObject=copy(raw).jsonObject.also{v->obj("version" to one,"wallet" to address,"items" to arr(512){x->val r=x.jsonObject;val kind=r.charterText("kind");require(kind in listOf("installation","service","expedition"));obj("kind" to choice(kind),"id" to if(kind=="expedition")id else v4,"idempotencyKey" to if(kind=="expedition")id else key,"baseId" to id,"createdAt" to if(kind=="expedition")time else journalTime,"status" to if(kind=="expedition")choice("accepted","returned") else choice("reserved","prepared","signed",if(kind=="installation")"installed" else "applied"))(r);if(kind=="expedition")require(r["id"]==r["idempotencyKey"])},"nextCursor" to nullable(cursor))(v);require(v.getValue("items").jsonArray.map{it.jsonObject.charterText("kind")+it.jsonObject.charterText("id")}.distinct().size==v.getValue("items").jsonArray.size)}
 fun assets(raw:JsonObject):JsonObject=copy(raw).jsonObject.also{obj("version" to one,"wallet" to address,"provenance" to choice("owner-attested-registry"),"items" to arr(512,obj("identity" to identity,"observedSlot" to n)),"nextCursor" to nullable(cursor))(it);val rows=it.getValue("items").jsonArray;require(rows.map{it.jsonObject.charterObject("identity").charterText("assetId")}.distinct().size==rows.size)}
 fun assetsV2(raw:JsonObject):JsonObject=copy(raw).jsonObject.also{v->obj("version" to {require(CharterGrammar.number(it)==2L)},"wallet" to address,"items" to arr(512,obj("identity" to identity,"observedSlot" to n,"provenance" to {x->val p=x.jsonObject;when(p.charterText("kind")){"owner_attested"->obj("kind" to choice("owner_attested"))(p);"finalized_issuance"->obj("kind" to choice("finalized_issuance"),"rootId" to {CharterGrammar.hex(it,16)})(p);else->error("Unrecognized vehicle provenance")}})),"nextCursor" to nullable(cursor))(v);val rows=v.getValue("items").jsonArray;require(rows.map{it.jsonObject.charterObject("identity").charterText("assetId")}.distinct().size==rows.size)}
 fun fleet(raw:JsonObject):JsonObject=copy(raw).jsonObject.also{v->obj("version" to one,"wallet" to address,"baseId" to id,"serverNow" to time,"acceptingNewActions" to bool,"vehicles" to arr(512,obj("installationId" to id,"berthId" to id,"family" to family,"tier" to tier,"revision" to {require(CharterGrammar.number(it)<9_007_199_254_740_991L)},"completedTotal" to counter,"allowanceStart" to counter,"remainingUses" to n,"away" to bool,"pendingService" to bool)))(v);val a=v.getValue("vehicles").jsonArray;for(k in listOf("installationId","berthId","family"))require(a.map{it.jsonObject[k]}.distinct().size==a.size)}
 fun routes(raw:JsonObject):JsonObject=copy(raw).jsonObject.also{v->obj("version" to one,"wallet" to address,"baseId" to id,"items" to arr(512,obj("installationId" to id,"previews" to arr(512){route(it)})))(v);val rows=v.getValue("items").jsonArray;require(rows.map{it.jsonObject["installationId"]}.distinct().size==rows.size);rows.forEach{val p=it.jsonObject.getValue("previews").jsonArray;require(p.map{it.jsonObject["routeId"]}.distinct().size==p.size)}}
 fun expedition(raw:JsonObject):JsonObject=copy(raw).jsonObject.also{v->obj("wallet" to address,"idempotencyKey" to id,"serverNow" to time,"status" to choice("unknown","accepted"),"receipt" to nullable(obj("wallet" to address,"request" to expeditionRequest,"expeditionId" to id,"installationId" to id,"route" to route,"departedAt" to time,"returnsAt" to time,"termId" to id,"termHash" to hash,"completedBefore" to {counter(it);require(CharterGrammar.amount(it)<Long.MAX_VALUE.toBigInteger())})),"return" to nullable(expeditionReturn))(v);val r=v.charterOptional("receipt");val end=v.charterOptional("return");require((v.charterText("status")=="unknown")== (r==null));if(r==null)require(end==null) else {val request=r.charterObject("request");val route=r.charterObject("route");require(r["wallet"]==v["wallet"]&&request["idempotencyKey"]==v["idempotencyKey"]&&r["expeditionId"]==v["idempotencyKey"]&&request["installationId"]==r["installationId"]&&request["routeId"]==route["routeId"]&&request["policyVersion"]==route["policyVersion"]);require(request["fitting"]==route["fitting"]?.jsonObject?.let(::equipmentSelection));require(Instant.parse(r.charterText("returnsAt"))==Instant.parse(r.charterText("departedAt")).plusSeconds(CharterGrammar.number(route.getValue("durationSec"))));end?.let{require(it["secondaryOutput"]==route["secondaryOutput"]);require(Instant.parse(it.charterText("returnedAt"))>=Instant.parse(r.charterText("returnsAt"))&&CharterGrammar.amount(it.getValue("completedTotal"))==CharterGrammar.amount(r.getValue("completedBefore"))+BigInteger.ONE)}}}
 fun collect(raw:JsonObject):JsonObject=copy(raw).jsonObject.also{obj("baseId" to id,"serverNow" to time,"returned" to n)(it)}
 private val cursor:Check={require(CharterGrammar.text(it).length in 1..256&&CharterGrammar.text(it).matches(Regex("[A-Za-z0-9_-]+")))}
 fun validateRequest(method:String,path:String,query:Map<String,String>,body:JsonObject?) {
  if(path.startsWith("/vehicles/craft/")){VehicleCraftProtocol.validateRequest(method,path,query,body);return}
  if(path=="/vehicles/client/assets-v2"){require(method=="GET"&&body==null&&query.keys.all{it=="cursor"});query["cursor"]?.let{cursor(JsonPrimitive(it))};return}
  require('?' !in path&&'#' !in path&&method in listOf("GET","POST"));val p=path.removePrefix("/").split('/');body?.let(::copy)
  if(method=="GET"){require(body==null);if(path in listOf("/vehicles/client/activity","/vehicles/client/assets")){require(query.keys.all{it=="cursor"});query["cursor"]?.let{cursor(JsonPrimitive(it))};return};if(path in listOf("/vehicles/client/routes","/vehicles/fleet")){require(query.keys.contains("baseId")&&query.keys.all{it=="baseId"||path=="/vehicles/client/routes"&&it=="policyVersion"});id(JsonPrimitive(query.getValue("baseId")));query["policyVersion"]?.let{require(it in listOf("1","2"))};return};require(query.isEmpty());if(p.size==3&&p.take(2)==listOf("advanced-expeditions","by-key")){id(JsonPrimitive(p[2]));return};require(p.take(2)==listOf("vehicles","client")&&p.getOrNull(2) in listOf("installations","services"));if(p.size==4){v4(JsonPrimitive(p[3]));return};require(p.size==5&&p[3]=="by-key");val decoded=URLDecoder.decode(p[4],"UTF-8");require(encodeKey(decoded)==p[4]);return}
  require(query.isEmpty());val b=requireNotNull(body);if(path=="/advanced-expeditions"){expeditionRequest(b);return};if(path=="/advanced-expeditions/collect"){obj("baseId" to id)(b);return};require(p.take(2)==listOf("vehicles","client")&&p.getOrNull(2) in listOf("installations","services"));if(p.size==3){if(p[2]=="installations")installRequest(b) else serviceRequest(b);return};require(p.size==5);v4(JsonPrimitive(p[3]));require(p[4] in listOf("prepare","signed","recover","review","deliver"));if(p[4]=="signed")obj("signedTransaction" to {require(CharterGrammar.base64(it).size>=66)})(b) else require(b.isEmpty())
 }
}

/** Frozen shared catalogue values are retained with each original. No Kotlin game
 * tuning copy; historical validation never follows a later current-policy pointer. */
data class VehiclePolicy(val raw:JsonObject) {
 val client get()=raw.charterObject("client");val vehicles get()=raw.charterObject("vehicles")
 fun bound(name:String)=CharterGrammar.number(client.getValue(name))
 val tiers get()=vehicles.getValue("tiers").jsonArray.map{CharterGrammar.number(it)}
 val ordinaryEquipment get()=raw["ordinaryEquipment"]?.jsonObject?.let(EquipmentPolicy::from)
 val ordinaryRoutes get()=raw["ordinaryRoutes"]?.jsonObject?.let{OrdinaryRoutes.from(it,tiers)}
 fun sameBurnPolicy(other:VehiclePolicy?)=other!=null&&JsonObject(raw-setOf("ordinaryRoutes","ordinaryEquipment"))==JsonObject(other.raw-setOf("ordinaryRoutes","ordinaryEquipment"))
 val routePolicyVersion get()=ordinaryRoutes?.policyVersion?:1L
 fun supportsRouteVersion(version:Long)=version==1L||ordinaryRoutes?.policyVersion==version
 val completedUses get()=CharterGrammar.number(vehicles.getValue("completedUsesPerInstall"))
 fun serviceEffect(input:JsonObject):JsonObject {serviceState(input);val used=CharterGrammar.amount(input.getValue("completedTotal"))-CharterGrammar.amount(input.getValue("allowanceStart"));require(used.signum()>=0&&used<=completedUses.toBigInteger());val current=CharterGrammar.number(input.getValue("tier"));require(current in tiers);val upgrade=input.charterText("operation")=="upgrade";val tierAfter=if(upgrade)tiers.getOrNull(tiers.indexOf(current)+1)?:error("Maximum vehicle tier") else current;require(upgrade||used==completedUses.toBigInteger());val start=if(upgrade)input.getValue("allowanceStart") else input.getValue("completedTotal")
  return buildJsonObject{put("version",1);for(k in listOf("operation","installationId","baseId","berthId","revision","family","tier","completedTotal","allowanceStart"))put(k,input.getValue(k));put("tierAfter",tierAfter);put("revisionAfter",Math.addExact(CharterGrammar.number(input.getValue("revision")),1));put("allowanceStartAfter",start);put("remainingUses",(completedUses.toBigInteger()-CharterGrammar.amount(input.getValue("completedTotal"))+CharterGrammar.amount(start)).toLong())}
 }
 fun verifyClient(raw:JsonObject){val c=VehicleProtocol.client(raw);require(CharterGrammar.number(VehicleProtocol.original(c).charterObject("identity").getValue("tier")) in tiers);if(c.charterText("kind")=="service"){val effect=serviceEffect(VehicleProtocol.original(c).charterObject("state"));VehicleProtocol.terminal(c)?.let{for(k in listOf("tierAfter","revisionAfter","completedTotal","allowanceStartAfter","remainingUses"))require(it[k]==effect[k])}}}
 fun verifyFleet(raw:JsonObject){val v=VehicleProtocol.fleet(raw);require(v.getValue("vehicles").jsonArray.size<=CharterGrammar.number(vehicles.getValue("advancedFamilyCount")));v.getValue("vehicles").jsonArray.forEach{val r=it.jsonObject;val used=CharterGrammar.amount(r.getValue("completedTotal"))-CharterGrammar.amount(r.getValue("allowanceStart"));require(CharterGrammar.number(r.getValue("tier")) in tiers&&used.signum()>=0&&used<=completedUses.toBigInteger()&&CharterGrammar.number(r.getValue("remainingUses")).toBigInteger()==completedUses.toBigInteger()-used)}}
 fun verifyRoute(value:JsonObject,current:Boolean=false){route(value);if("fitting" in value){verifyRoute(requireNotNull(ordinaryEquipment).original(value),current);return};if(CharterGrammar.number(value.getValue("policyVersion"))!=1L){requireNotNull(ordinaryRoutes){"This saved route needs its installed catalogue"}.verify(value,this);return};val advanced=raw.charterObject("advanced");val policy=advanced.charterObject("v1");require(value["policyVersion"]==policy["policyVersion"]&&(!current||value["policyVersion"]==advanced["currentPolicyVersion"]));val family=value.charterText("family");val tier=CharterGrammar.number(value.getValue("tier"));require(tier in tiers);val routeId=value.charterText("routeId");val profile=policy.charterObject("families").charterObject(family);val paid=raw.charterObject("paidRoutes").charterObject("routes")[routeId];if(paid==null)require(JsonPrimitive(routeId) in profile.getValue("homeRoutes").jsonArray)
  val destination=paid?.let(CharterGrammar::text)?:value.charterText("homeRealmId");require(value.charterText("realmId")==destination&&starterResourceRealms[value.charterText("resourceId")]==destination&&value.charterText("accessRequirement")==if(paid==null)"home" else "paid_realm")
  val alternate=if(family=="survey_balloon"&&paid==null)policy.charterObject("balloonAlternateHome")[routeId]?.jsonObject else null
  val duration=alternate?.get("durationSec")?:profile.getValue("durationSecByTier").jsonArray[(tier-1).toInt()];val gross=CharterGrammar.number(alternate?.get("grossRaw")?:profile.getValue("grossRawByTier").jsonArray[(tier-1).toInt()]).toBigInteger();val numerator=gross*CharterGrammar.number(policy.getValue("islandPoolBps")).toBigInteger();val denominator=CharterGrammar.number(policy.getValue("basisPoints")).toBigInteger();require(denominator.signum()>0&&numerator%denominator==BigInteger.ZERO);val tax=numerator/denominator
  require(value["durationSec"]==duration&&CharterGrammar.amount(value.getValue("grossQuantity"))==gross&&CharterGrammar.amount(value.getValue("islandPoolQuantity"))==tax&&CharterGrammar.amount(value.getValue("netQuantity"))==gross-tax)
  val supplies=profile.getValue("supplies").jsonArray.map{it.jsonObject}.sortedBy{it.charterText("resourceId")}.map{buildJsonObject{put("resourceId",it.getValue("resourceId"));put("quantity",CharterGrammar.number(it.getValue("quantity")).toString())}};require(value["supplies"]==JsonArray(supplies))
 }
 fun verifyRoutes(raw:JsonObject,policyVersion:Long=1){require(supportsRouteVersion(policyVersion));val v=VehicleProtocol.routes(raw);require(v.getValue("items").jsonArray.size<=CharterGrammar.number(vehicles.getValue("advancedFamilyCount")));v.getValue("items").jsonArray.forEach{it.jsonObject.getValue("previews").jsonArray.forEach{require(CharterGrammar.number(it.jsonObject.getValue("policyVersion"))==policyVersion);verifyRoute(it.jsonObject,true)}}}
 fun verifyExpedition(raw:JsonObject){VehicleProtocol.expedition(raw).charterOptional("receipt")?.let{verifyRoute(it.charterObject("route"))}}
 fun verifyReview(raw:JsonObject,client:JsonObject){val r=VehicleProtocol.review(raw);require(r["reference"]==VehicleProtocol.reference(client)&&r.charterText("wallet")==VehicleProtocol.actor(client));require(Instant.parse(r.charterText("expiresAt"))==Instant.parse(r.charterText("reviewedAt")).plusMillis(bound("reviewMaxAgeMs")));val p=client.charterObject("record").charterOptional("preparation");require(r["messageSha256"]==(p?.get("messageSha256")?:JsonNull));r.charterOptional("observation")?.let{o->require(p!=null&&o["blockhash"]==p["blockhash"]&&o["lastValidBlockHeight"]==p["lastValidBlockHeight"]&&CharterGrammar.number(o.getValue("ownerSlot"))>=CharterGrammar.number(p.getValue("blockhashContextSlot"))&&CharterGrammar.amount(o.getValue("networkFeeLamports"))<=bound("maxNetworkFeeLamports").toBigInteger())}}
 companion object {
  fun from(raw:JsonObject):VehiclePolicy {val v=VehicleProtocol.copy(raw).jsonObject;require(v.keys.containsAll(setOf("client","vehicles","advanced","paidRoutes"))&&v.keys.all{it in setOf("client","vehicles","advanced","paidRoutes","ordinaryRoutes","ordinaryEquipment")});val c=v.charterObject("client");require(c.keys==setOf("version","reviewMaxAgeMs","rpcTimeoutMs","maxPendingRpc","maxNetworkFeeLamports","discoveryPageSize","localPendingLimit","localArchiveLimit"));c.values.forEach{positive(it)};require(CharterGrammar.number(c.getValue("version"))==1L);val p=VehiclePolicy(v);require(p.tiers.isNotEmpty()&&p.tiers.distinct()==p.tiers&&p.tiers.all{it in 1..255}&&p.completedUses>0);for(k in listOf("localPendingLimit","localArchiveLimit","discoveryPageSize"))require(p.bound(k) in 1..512);p.ordinaryRoutes;p.ordinaryEquipment;return p}
  fun catalogue(catalogue:JsonObject?):VehiclePolicy?=runCatching{val c=requireNotNull(catalogue).charterObject("constants");from(buildJsonObject{put("client",c.getValue("PHASE_E_VEHICLE_CLIENT"));put("vehicles",c.getValue("PHASE_E_VEHICLES"));put("advanced",c.getValue("PHASE_E_ADVANCED_EXPEDITIONS"));put("paidRoutes",c.getValue("PHASE_E_PAID_STARTER_ROUTES"));c["PHASE_E_ORDINARY_ROUTES"]?.let{put("ordinaryRoutes",it)};EquipmentPolicy.catalogue(catalogue)?.let{put("ordinaryEquipment",it.raw)}})}.getOrNull()
 }
}
